void UCDHudGen::Draw_BP_CommanderHUD(ACDHudBase* Hud, int32 SizeX, int32 SizeY)
{
	using namespace CDHudGen_BP_CommanderHUD;
	ACDHudBase* Self = Hud;
	if (!Self) { return; }
	FState* St = &StateFor(Self);
	const int32 Epoch = UCDHudLayers::GetLayerEpoch(LayerName());
	if (St->Epoch != Epoch) { St->ResetValues(); St->Epoch = Epoch; }   // fresh frame after a switch (rule R3)
	FCtx C{ Self, *St };
	C.S.o_K2Node_Event_0_SizeX = SizeX; C.S.o_K2Node_Event_0_SizeY = SizeY;
	N_K2Node_CallParentFunction_0(C);
}